export type ShellType = 'powershell' | 'cmd' | 'bash' | 'termux';

export type RiskLevel = 'low' | 'medium' | 'high';

/** A command TermiAI generated. Commands are copy-only — TermiAI never runs them. */
export interface Command {
  id: string;
  prompt: string;
  command: string;
  explanation: string;
  risk: RiskLevel;
  caveat: string;
  shell: ShellType;
  timestamp: Date;
  /** 'ai' = generated by Claude; 'demo' = offline keyword fallback. */
  source: 'ai' | 'demo';
}

export interface TerminalConfig {
  shell: ShellType;
  showWarnings: boolean;
  maxHistory: number;
}

export interface GeneratedCommand {
  command: string;
  explanation: string;
  risk: RiskLevel;
  caveat: string;
  source: 'ai' | 'demo';
}
